# [LATER-STEP] spoken_brief.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef generate_spoken_brief(text: str) -> bytes:\n    \"\"\"Generate a spoken (audio) brief from the model output using a TTS provider.\"\"\"\n    provider = os.getenv(\"PROVIDER\", \"watson\").lower()\n    if provider == \"watson\":\n        # IBM Watson Text to Speech\n        from ibm_watson import TextToSpeechV1\n        from ibm_cloud_sdk_core.authenticators import IAMAuthenticator\n        authenticator = IAMAuthenticator(os.getenv(\"IBM_TTS_APIKEY\"))\n        tts = TextToSpeechV1(authenticator=authenticator)\n        tts.set_service_url(os.getenv(\"IBM_TTS_URL\"))\n        audio = tts.synthesize(\n            text=text,\n            accept=\"audio/wav\",\n            voice=\"en-US_MichaelV3Voice\",\n        ).get_result()\n        return audio.content\n    elif provider == \"azure\":\n        from azure.cognitiveservices.speech import SpeechConfig, AudioConfig, SpeechSynthesizer\n        speech_config = SpeechConfig(\n            subscription=os.getenv(\"AZURE_SPEECH_KEY\"),\n            region=os.getenv(\"AZURE_SPEECH_REGION\"),\n        )\n        audio_config = AudioConfig(output_format=\"WAV\")\n        synthesizer = SpeechSynthesizer(speech_config, audio_config=audio_config)\n        result = synthesizer.speak_text_async(text).get()\n        # Convert to bytes (result.audio_data is already bytes)\n        return result.audio_data\n    elif provider == \"dashscope\":\n        import dashscope\n        dashscope.api_key = os.getenv(\"DASHSCOPE_API_KEY\")\n        resp = dashscope.cosy_voice(\n            text=text,\n            model=\"cosy-voice-mini\",\n            **{\"format\": \"wav\"},\n        )\n        # Assume resp contains wav binary in resp['audio']\n        return resp[\"audio\"]\n    elif provider == \"elevenlabs\":\n        import elevenlabs\n        eleven_api = elevenlabs.Api(os.getenv(\"ELEVENLABS_API_KEY\"))\n        audio = eleven_api.generate_cloning_voice(text=text, model_id=\"eleven_monolingual_v1\")\n        # The SDK may return URL or bytes; here we return the URL placeholder\n        return audio.encode()\n    elif provider == \"amazon\":\n        import boto3\n        polly = boto3.client(\"polly\")\n        response = polly.synthesize_speech(\n            Text=text,\n            OutputFormat=\"mp3\",\n            VoiceId=\"Joanna\",\n        )\n        return response[\"AudioStream\"].read()\n    elif provider == \"google\":\n        from google.cloud import texttospeech\n        client = texttospeech.TextToSpeechClient()\n        synthesis_input = texttospeech.SynthesisInput(text=text)\n        voice = texttospeech.VoiceSelectionParams(language_code=\"en-US\", name=\"en-US-Wavenet-D\")\n        audio_config = texttospeech.AudioConfig(audio_encoding=texttospeech.AudioEncoding.MP3)\n        response = client.synthesize_speech(input=synthesis_input, voice=voice, audio_config=audio_config)\n        return response.audio_content\n    else:\n        raise ValueError(f\"Unsupported PROVIDER for TTS: {provider}\")\n